<?php require_once 'includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!current_user()){$_SESSION['flash']='Sign in to keep your saved watches across visits.';header('Location: login.php');exit;}$id=(int)($_POST['product_id']??0);$p=find_product($conn,$id);if($p){$st=$conn->prepare('SELECT product_id FROM wishlist WHERE username=? AND product_id=?');$user=$_SESSION['user'];$st->bind_param('si',$user,$id);$st->execute();$exists=$st->get_result()->fetch_assoc();if($exists){$d=$conn->prepare('DELETE FROM wishlist WHERE username=? AND product_id=?');$d->bind_param('si',$user,$id);$d->execute();}else{$i=$conn->prepare('INSERT IGNORE INTO wishlist(username,product_id) VALUES(?,?)');$i->bind_param('si',$user,$id);$i->execute();}}$dest=$_SERVER['HTTP_REFERER']??'wishlist.php';if(strpos($dest,'://')!==false)$dest='wishlist.php';header('Location: '.$dest);exit;}$pageTitle='Saved timepieces | Samay';$savedIds=wishlist_ids($conn);$products=[];if(current_user()&&$savedIds){$all=get_products($conn);foreach($all as $p)if(in_array((string)$p['id'],$savedIds,true))$products[]=$p;}require 'includes/header.php'; ?>
<section class="page-intro"><div class="kicker">Your personal edit</div><h1>Saved with love.</h1><p>Your shortlist of timepieces that caught your eye.</p></section><section class="section"><?php if(!current_user()): ?><div class="empty-state"><h2>Keep your favourites close.</h2><p>Sign in to save watches and find them here whenever you return.</p><a class="button" href="login.php">Sign in to view saved items</a></div><?php elseif($products): ?><div class="product-grid"><?php foreach($products as $p)require 'includes/product-card.php'; ?></div><?php else: ?><div class="empty-state"><h2>A little space for your favourites.</h2><p>Tap the heart on any timepiece to add it to your saved list.</p><a class="button" href="session/index.php">Explore the collection</a></div><?php endif; ?></section><?php require 'includes/footer.php'; ?>
